def transform(grid):
    bg = grid[0][0]
    fg = None
    for val in grid:
        for v in val:
            if v != bg:
                fg = v
                break
        if fg:
            break

    # Find all pixels of fg and their bounding box
    rows_has_fg = set()
    cols_has_fg = set()
    for r in range(len(grid)):
        for c in range(len(grid[0])):
            if grid[r][c] == fg:
                rows_has_fg.add(r)
                cols_has_fg.add(c)

    # Get min and max with some margin to find relevant 3x3 region
    min_r = min(rows_has_fg)
    max_r = max(rows_has_fg)
    min_c = min(cols_has_fg)
    max_c = max(cols_has_fg)

    # Check each 3x3 region overlapping the fg pixels
    candidate_regions = []
    for r in range(max(0, min_r - 2), min(len(grid), max_r + 1)):
        for c in range(max(0, min_c - 2), min(len(grid[0]), max_c + 1)):
            region = [[grid[r+i][c+j] for j in range(3)] for i in range(3)]
            # Count fg pixels
            fg_count = sum(1 for i in range(3) for j in range(3) if region[i][j] == fg)
            if fg_count >= 2:  # At least 2 foreground pixels
                candidate_regions.append((r, c, fg_count, region))

    if candidate_regions:
        # Return region with most foreground, or first if tied
        candidate_regions.sort(key=lambda x: (-x[2], x[0], x[1]))
        return candidate_regions[0][3]
    else:
        return [[bg, bg, bg], [bg, bg, bg], [bg, bg, bg]]

